def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    # The horizontal trunk is the row containing the two end markers.
    trunk_rows = [r for r, cols in by_row.items() if len(cols) == 2]
    if len(trunk_rows) != 1:
        raise ValueError('expected exactly one row with two markers')
    trunk = trunk_rows[0]
    ends = by_row[trunk]
    for c in range(min(ends), max(ends) + 1):
        if out[trunk][c] == 0:
            out[trunk][c] = 3
    for r, c in points:
        if r == trunk:
            continue
        step = 1 if trunk > r else -1
        for rr in range(r + step, trunk, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
